pages['notifications']='''<view class="row between margin"><view class="title">通知中心</view><text class="accent" bindtap="readAll">全部已读</text></view><view class="tabs"><view class="{{tab===''?'on':''}}" bindtap="tabChange" data-tab="">全部</view><view class="{{tab==='homework'?'on':''}}" bindtap="tabChange" data-tab="homework">作业</view><view class="{{tab==='course'?'on':''}}" bindtap="tabChange" data-tab="course">课程</view></view><view class="card"><view class="list-item" wx:for="{{filtered}}" wx:key="id" bindtap="openNotice" data-item="{{item}}"><view class="avatar">信</view><view class="grow"><view class="title">{{item.title}}</view><view class="sub">{{item.text}}</view><view class="sub">{{item.date}}</view></view><text class="pill {{item.read?'':'red-pill'}}">{{item.read?'已读':'未读'}}</text></view><view class="empty" wx:if="{{!filtered.length}}">暂无通知</view></view>'''
pages['me']='''<view class="hero row" bindtap="go" data-page="profile"><view class="avatar large light">我</view><view class="grow"><view class="title">{{me.name}}</view><view>{{me.phone||'开发测试身份'}}</view></view><text>个人资料 ›</text></view><view class="card"><view class="list-item" bindtap="openStudents"><view class="grow title">我的学员</view><text class="sub">{{students.length}} 位 · 切换 ›</text></view><view class="list-item" bindtap="go" data-page="notifications"><view class="grow title">通知中心</view><text>›</text></view><view class="list-item" bindtap="go" data-page="hours"><view class="grow title">我的课时</view><text>›</text></view><view class="list-item" bindtap="go" data-page="schedule"><view class="grow title">班级与课表</view><text>›</text></view><view class="list-item" bindtap="go" data-page="recordings"><view class="grow title">缺课与补看申请</view><text>›</text></view></view><view class="card"><view class="list-item" bindtap="go" data-page="content" data-kind="introduction"><view class="grow title">关于叶芝英语</view><text>›</text></view><view class="list-item" bindtap="go" data-page="content" data-kind="enrollment"><view class="grow title">报名须知</view><text>›</text></view><view class="list-item" bindtap="support"><view class="grow title">联系客服</view><text>›</text></view><view class="list-item" bindtap="go" data-page="settings"><view class="grow title">设置</view><text>›</text></view></view>'''
pages['profile']='''<view class="card"><view class="section-title"><view class="dot"/>个人资料</view><view class="sub">家长称呼</view><input class="field" value="{{profileName}}" data-field="profileName" bindinput="input" maxlength="40" placeholder="填写家长称呼"/><view class="list-item"><text class="grow">授权手机号</text><text>{{me.phone||'开发测试身份'}}</text></view><view class="sub">手机号或监护关系变更，请联系机构核验。</view><button class="primary" bindtap="saveProfile" loading="{{busy}}">保存资料</button></view><button class="ghost margin" bindtap="support">联系机构</button>'''
pages['settings']='''<view class="card"><view class="list-item" bindtap="subscriptions"><view class="grow title">微信订阅消息</view><text>授权 ›</text></view><view class="sub">拒绝订阅不影响学习记录、作业提交及站内通知。</view><view class="list-item" bindtap="go" data-page="content" data-kind="privacy"><view class="grow title">隐私政策</view><text>›</text></view><view class="list-item" bindtap="go" data-page="content" data-kind="agreement"><view class="grow title">用户协议</view><text>›</text></view><view class="list-item" bindtap="support"><view class="grow title">更正资料与账号注销咨询</view><text>›</text></view></view><button class="ghost margin" bindtap="logout" loading="{{busy}}">退出登录</button>'''
pages['content']='''<view wx:for="{{items}}" wx:key="id" class="card"><view class="title">{{item.title}}</view><view class="body-text">{{item.text}}</view><media-files files="{{item.files}}" student="{{studentId}}"/></view><view wx:if="{{!items.length && !loading}}" class="empty">机构尚未发布此项内容，请联系机构获取说明。</view>'''
header='''<view wx:if="{{testMode}}" class="test-banner">开发测试环境 · 仅使用受控测试数据</view><view class="student-bar" wx:if="{{student}}"><view class="row grow" bindtap="openStudents"><view class="avatar small">学</view><view>{{student.name}} <text class="small">{{student.grade}} ▾</text></view></view><view bindtap="go" data-page="notifications">通知<text wx:if="{{data.unread}}" class="badge">{{data.unread}}</text></view></view><view wx:if="{{loading}}" class="loading">正在加载…</view><view wx:if="{{error}}" class="error-box"><view>{{error}}</view><button class="ghost" size="mini" bindtap="load">重新加载</button></view>'''
footer='''<view wx:if="{{!student && !loading && !error && name!=='profile' && name!=='settings' && name!=='teachers' && name!=='teacher-detail' && name!=='content' && name!=='me'}}" class="card empty"><view class="title">暂未关联学员</view><view class="sub">请联系机构核对报名时预留的手机号。机构完成预登记后，重新授权即可关联。</view><button class="primary" bindtap="support">联系机构</button></view><view wx:if="{{showStudents}}" class="mask" bindtap="closeStudents"><view class="sheet"><view class="sheet-title">选择学员</view><view class="sheet-body"><view wx:for="{{students}}" wx:key="id" class="list-item {{item.id===studentId?'soft':''}}" bindtap="chooseStudent" data-id="{{item.id}}"><view class="avatar">学</view><view class="grow"><view class="title">{{item.name}} {{item.id===studentId?'✓':''}}</view><view class="sub">{{item.grade}} · 剩余 {{item.remaining}} 课时</view></view></view></view><view class="sheet-footer"><button class="ghost" bindtap="support">管理关联（联系机构）</button></view></view></view><view wx:if="{{showSupport}}" class="mask"><view class="sheet"><view class="sheet-title">企业微信客服</view><view class="sheet-body center"><image wx:if="{{supportUrl}}" src="{{supportUrl}}" class="qr" mode="aspectFit" show-menu-by-longpress/><view wx:else class="empty">机构尚未配置客服二维码</view><view class="body-text">{{support.text||'约课、调课、报名与缴费由机构线下办理。请通过已知机构联系方式咨询。'}}</view><view class="error" wx:if="{{supportError}}">{{supportError}}</view></view><view class="sheet-footer"><button class="ghost" bindtap="closeSupport">关闭</button></view></view></view><view class="safe-bottom"/>'''
for name,body in pages.items():
    folder=root/'pages'/name
    if folder.exists():raise SystemExit('Refusing to overwrite '+str(folder))
    folder.mkdir(parents=True)
    (folder/'index.ts').write_text("import { registerPage } from '../../services/page';\nregisterPage('"+name+"');\n",encoding='utf-8')
    (folder/'index.json').write_text(json.dumps({'usingComponents':{'media-files':'/components/media-files/index'},'enablePullDownRefresh':True},ensure_ascii=False),encoding='utf-8')
    (folder/'index.wxml').write_text(body if name=='login' else header+body+footer,encoding='utf-8')
    (folder/'index.wxss').write_text('',encoding='utf-8')
app={'pages':['pages/'+x+'/index' for x in pages], 'window':{'navigationBarTitleText':'叶芝英语','navigationBarBackgroundColor':'#FF8A00','navigationBarTextStyle':'white','backgroundColor':'#FFF8F0'},'tabBar':{'color':'#9C8A76','selectedColor':'#F26A00','backgroundColor':'#FFFFFF','borderStyle':'white','list':[{'pagePath':'pages/'+n+'/index','text':t,'iconPath':'assets/'+n+'.png','selectedIconPath':'assets/'+n+'-on.png'} for n,t in [('home','首页'),('homework','作业'),('knowledge','知识库'),('me','我的')]]},'style':'v2','lazyCodeLoading':'requiredComponents','sitemapLocation':'sitemap.json'}
(root/'app.json').write_text(json.dumps(app,ensure_ascii=False,indent=2),encoding='utf-8')
(root/'sitemap.json').write_text('{"rules":[{"action":"disallow","page":"*"}]}',encoding='utf-8')
print('Created',len(pages),'native routes')
